----------------------------------------------------------------------
-- VoidProf Planner -- the cheapest leveling path for each crafting
-- profession from what you have, worked out live. VoidProf is the profession
-- brain; VoidAH shows what to buy and the prices, VoidGather counts your
-- characters' materials (the user's split, 2026-11-03; this was VoidAH's
-- ProfessionPlans.lua before). Shown in VoidProf's profession tabs
-- (LevelUI.lua) and VoidAH's Professions tab.
--
-- Recipes come from Blizzard's game tables (ProfessionData.lua, generated by
-- voidscout-data/tools/cmd/prof-data): when each recipe turns yellow and grey,
-- how many points it gives, its materials and what it makes. Prices are your own:
--   1. VoidAH's Auction House scan data (the cheapest quality of a material),
--   2. vendor prices VoidAH saw at a merchant you visited (VoidAH_Price),
--   3. else the game's listed buy price, marked "est." (exact for vendor goods).
-- Recipes you know come first (VoidProf:ProfCache(), per character, captured in Core.lua when
-- you open the profession window); where none of them gives skill, the
-- cheapest one you don't know yet is used and flagged NOT LEARNED.
--
-- The path: from your skill to the cap, each craft is the recipe with the
-- lowest cost per expected skill point. Orange always gives its points; past
-- yellow the chance falls off to 0 at grey ((grey - skill) / (grey - yellow)).
--
-- What you already own is used first (2026-11-03: the user wanted the plan to
-- use what their characters hold). With VoidGather: every character's bags +
-- bank as it last counted them, plus the warband bank; without: this
-- character and the warband bank. Owned materials cost a quarter of their
-- price when picking recipes, so the path prefers your stock but won't burn
-- 500g of ore to save 5g. The materials list is only what's left to buy; the
-- notes say what to take from which character.
--
-- A material can also be made instead of bought, when that's cheaper: with a
-- recipe you know (Inscription's inks), or for Inscription by milling herbs
-- into pigments (MILL below; the user asked for inks from herbs, 2026-11-03).
-- The notes list those under "Make first".
--
-- VoidProf.Planner:List() = one entry per profession; :Build(entry) returns
-- { name, skill, notes, steps = { startSkill, endSkill, recipe, spellID, count,
--   per, source, known }, mats = { { qty, name, itemID, priceText } },
--   craftNow = { { name, crafts } }, made = { "Mill ..." }, fromOwn = { "..." },
--   summary, skillLevel, maxSkillLevel, skillUnknown }.
----------------------------------------------------------------------

VoidProf = VoidProf or {}
local Planner = {}
VoidProf.Planner = Planner

local DATA = VoidProf.ProfessionData or { professions = {}, items = {} }
local MAX_SKILL = 100

local entries = {}
for _, p in ipairs(DATA.professions) do
    entries[#entries + 1] = { id = p.id, name = p.name, skill = p.name, data = p }
end

function Planner:List() return entries end

function Planner:Find(profName)
    for _, e in ipairs(entries) do
        if e.name == profName or e.id == profName then return e end
    end
end

-- The recipes you know of a profession, as this character's profession window
-- last showed them (Core.lua). Not VoidAH's copy: that one is account-wide, so
-- it can be another character's.
local function RecipeCache(profName)
    return VoidProf.ProfCache and VoidProf:ProfCache()[profName]
end

----------------------------------------------------------------------
-- Prices
----------------------------------------------------------------------
-- Cheapest way to get one of a material (any quality): price, source, itemID.
-- VoidAH (optional) knows Auction House and merchant prices.
local function UnitPrice(ids)
    local best, src, bestID
    if VoidAH_Price then
        for _, id in ipairs(ids) do
            local p, s = VoidAH_Price(id)
            if p and p > 0 and (not best or p < best) then best, src, bestID = p, s, id end
        end
    end
    if not best then
        local it = DATA.items[ids[1]]
        if it and (it.buy or 0) > 0 then best, src, bestID = it.buy, "est", ids[1] end
    end
    return best, src, bestID or ids[1]
end

local function ItemName(id)
    return C_Item.GetItemNameByID(id) or (DATA.items[id] and DATA.items[id][1]) or ("item " .. id)
end

local function Money(copper)
    if VoidUI and VoidUI.FormatMoney then return VoidUI:FormatMoney(math.floor(copper + 0.5)) end
    return string.format("%.1fg", copper / 10000)
end
Planner.Money = Money

----------------------------------------------------------------------
-- What you already own
----------------------------------------------------------------------
local OWN_WEIGHT = 0.25   -- what an owned material costs when picking recipes, x its price

-- How many of item `id` you have and where: total, { here = n, warband = n,
-- ["Name-Realm"] = n }. VoidGather (optional) knows your other characters.
local function Owned(id)
    local G = _G.VoidGather and _G.VoidGather.Goals
    if G and G.Where then
        local ok, where = pcall(G.Where, G, { id })
        if ok and type(where) == "table" then
            local n = 0
            for _, c in pairs(where) do n = n + c end
            return n, where, true
        end
    end
    local here = C_Item.GetItemCount(id, true, false, true, false) or 0
    local all = C_Item.GetItemCount(id, true, false, true, true) or 0
    return all, { here = here, warband = math.max(0, all - here) }, false
end

-- What disenchanting the spare gear VoidGear's Spares tab marks "disenchant"
-- should give, as extra stock: { [itemID] = n } (the lowest rank of each
-- material; one per piece is VoidGear's estimate). The user asked for this so
-- the Enchanting plan stops buying crystals their old gear holds (2026-11-03).
-- Read once per plan: Judge goes through every bag and bank.
local function DisenchantStock()
    local SP = _G.VoidGear and _G.VoidGear.Spares
    if not (SP and SP.Judge and SP.DE_MAT) then return {} end
    local ok, res = pcall(SP.Judge, SP)
    if not (ok and type(res) == "table" and type(res.deMats) == "table") then return {} end
    local out = {}
    for q, n in pairs(res.deMats) do
        local ids = SP.DE_MAT[q]
        if ids and ids[1] and n > 0 then out[ids[1]] = (out[ids[1]] or 0) + n end
    end
    return out
end

-- "Alt" (class colored with VoidGather), "Name-OtherRealm" off-realm.
local function Who(key)
    if key == "here" then return "this character" end
    if key == "warband" then return "warband bank" end
    if key == "disenchant" then return "disenchanting your spare gear" end
    local G = _G.VoidGather and _G.VoidGather.Goals
    if G and G.Who then
        local ok, s = pcall(G.Who, G, key)
        if ok and s then return s end
    end
    local name, realm = key:match("^([^%-]+)%-(.+)$")
    return (name and realm == (GetNormalizedRealmName and GetNormalizedRealmName())) and name or key
end

-- "here 10, warband bank 20, Alt 30": where `need` of them come
-- from, this character first, then the warband bank, then the biggest piles,
-- then what disenchanting your spare gear gives.
local function FromText(where, need)
    local keys = {}
    for k, n in pairs(where) do
        if n > 0 and k ~= "here" and k ~= "warband" and k ~= "disenchant" then keys[#keys + 1] = k end
    end
    table.sort(keys, function(a, b) return where[a] > where[b] end)
    table.insert(keys, 1, "warband")
    table.insert(keys, 1, "here")
    keys[#keys + 1] = "disenchant"
    local parts = {}
    for _, k in ipairs(keys) do
        if need <= 0 then break end
        local take = math.min(need, where[k] or 0)
        if take > 0 then
            parts[#parts + 1] = Who(k) .. " " .. take
            need = need - take
        end
    end
    return table.concat(parts, ", ")
end

----------------------------------------------------------------------
-- Milling (Inscription): herbs -> pigments for inks
----------------------------------------------------------------------
-- Midnight Milling crushes 10 herbs; each herb gives its own pigment
-- (public game data, 2026-11-03; rank 1 then rank 2 ids). How
-- many isn't in the game's tables (server loot), so it's learned from your
-- own milling below; until then MILL_YIELD_EST, from the user's own log
-- (11-15 Powder Pigment per 10 Tranquility Bloom, 2026-11-03).
local MILL_SPELL = 1269575   -- Midnight Milling
local MILL_YIELD_EST = 1.2   -- pigments per herb
local MILL_HERBS = 10        -- herbs per mill
local MILL = {
    { key = "powder",      herbs = { 236761, 236767 }, pigments = { 245807, 245808 } },   -- Tranquility Bloom
    { key = "argentleaf",  herbs = { 236776, 236777 }, pigments = { 245803, 245804 } },
    { key = "sanguithorn", herbs = { 236770, 236771 }, pigments = { 245865, 245864 } },
    { key = "manalily",    herbs = { 236778, 236779 }, pigments = { 245867, 245866 } },
}
local millOf = {}   -- pigment itemID -> MILL entry
for _, e in ipairs(MILL) do
    for _, id in ipairs(e.pigments) do millOf[id] = e end
end

-- Pigments per herb: what you've milled (20+ herbs), else the estimate.
local function MillYield(e)
    local y = VoidProfDB and VoidProfDB.millYield and VoidProfDB.millYield[e.key]
    if y and (y.herbs or 0) >= 20 and (y.out or 0) > 0 then return y.out / y.herbs, false end
    return MILL_YIELD_EST, true
end

-- Learning it: from a Midnight Milling cast until 5 seconds after the last
-- one, herbs that left and pigments that arrived (bags, bank and warband
-- bank: crafting can use those) are added up per herb, from bag changes, so
-- a mill whose herbs go in one update and pigments in the next still adds
-- up. Then only herbs that both went down by a whole mill and got their own
-- pigment are kept, so a pigment bought or herbs used for something else
-- right then don't count.
local millAt, millSnap, millRun = 0, nil, nil
local function MillCommit()
    if GetTime() - millAt < 5 or not millRun then return end
    VoidProfDB = VoidProfDB or {}
    VoidProfDB.millYield = VoidProfDB.millYield or {}
    for key, r in pairs(millRun) do
        if r.herbs >= MILL_HERBS and r.out > 0 then
            local y = VoidProfDB.millYield[key] or { herbs = 0, out = 0 }
            y.herbs, y.out = y.herbs + r.herbs, y.out + r.out
            VoidProfDB.millYield[key] = y
        end
    end
    millRun = nil
end
local function MillCounts()
    local t = {}
    for _, e in ipairs(MILL) do
        local h, g = 0, 0
        for _, id in ipairs(e.herbs) do h = h + (C_Item.GetItemCount(id, true, false, true, true) or 0) end
        for _, id in ipairs(e.pigments) do g = g + (C_Item.GetItemCount(id, true, false, true, true) or 0) end
        t[e.key] = { h = h, g = g }
    end
    return t
end
local millWatch = CreateFrame("Frame")
millWatch:RegisterEvent("BAG_UPDATE_DELAYED")
millWatch:RegisterEvent("PLAYER_ENTERING_WORLD")
millWatch:RegisterUnitEvent("UNIT_SPELLCAST_SUCCEEDED", "player")
millWatch:SetScript("OnEvent", function(_, event, ...)
    if event == "UNIT_SPELLCAST_SUCCEEDED" then
        local spellID = select(3, ...)
        if spellID and not (issecretvalue and issecretvalue(spellID)) and spellID == MILL_SPELL then
            millAt = GetTime()
            millRun = millRun or {}
            C_Timer.After(5.5, MillCommit)
        end
        return
    end
    local now = MillCounts()
    if millSnap and millRun and GetTime() - millAt < 5 then
        for key, c in pairs(now) do
            local before = millSnap[key]
            local used, got = math.max(0, before.h - c.h), math.max(0, c.g - before.g)
            if used > 0 or got > 0 then
                local r = millRun[key] or { herbs = 0, out = 0 }
                r.herbs, r.out = r.herbs + used, r.out + got
                millRun[key] = r
            end
        end
    end
    millSnap = now
end)

----------------------------------------------------------------------
-- The plan
----------------------------------------------------------------------
function Planner:Build(entry, skill)
    local prof = entry and entry.data
    if not prof then return entry end
    local cache = RecipeCache(entry.skill)
    local known = cache and cache.recipes
    -- Always the expansion's cap: a recipe sync remembers the cap of its day
    -- (a week-old one said 75 while the real cap was 100).
    local target = MAX_SKILL

    -- What you own, read as each material comes up: owned / where for the
    -- notes, value = the AH price of one. A stock table (Fresh) starts at what
    -- you own and goes down as the path uses it; Scratch(p) is a view over one
    -- to try something without using anything up.
    local owned, where, value = {}, {}, {}
    local allChars = false
    local deStock = DisenchantStock()   -- dust / shards / crystals your spare gear gives
    local function Load(id)
        if owned[id] == nil then
            local n, w, all = Owned(id)
            local d = deStock[id]
            if d then
                n = n + d
                w = w or {}
                w.disenchant = d
            end
            owned[id], where[id] = n, w
            allChars = allChars or all
            value[id] = n > 0 and (UnitPrice({ id })) or 0
        end
        return owned[id]
    end
    -- noDE: without what disenchanting would give ("Craft now" means now)
    local function Fresh(noDE)
        return setmetatable({}, { __index = function(t, id)
            local n = type(id) == "number" and Load(id) or 0   -- "x"..id: made in the plan, none yet
            if noDE and where[id] and where[id].disenchant then n = n - where[id].disenchant end
            rawset(t, id, n)
            return n
        end })
    end
    local function Scratch(p) return setmetatable({}, { __index = p }) end
    local pool = Fresh()
    local canMill = prof.id == "inscription"
    local noBuy = false   -- true: only what you have (and can make from it) counts ("Craft now")

    -- Every recipe with its materials and their prices (price nil = none yet:
    -- the recipe can still be used while you own enough of it).
    local recipes, unpriced = {}, 0
    for _, r in ipairs(prof.recipes) do
        local id = r[1]
        local isKnown = (known and known[id] ~= nil)
            or (C_SpellBook and C_SpellBook.IsSpellKnown and C_SpellBook.IsSpellKnown(id)) or false
        local est, mats, priced = false, {}, true
        for _, m in ipairs(r.mats) do
            local price, src, itemID = UnitPrice(m.ids)
            if not price then priced = false end
            if src == "est" then est = true end
            mats[#mats + 1] = { id = itemID, ids = m.ids, n = m.n, price = price }
        end
        if not priced then unpriced = unpriced + 1 end   -- said in the notes if the path stops short
        recipes[#recipes + 1] = { id = id, name = r[2], min = r.min, yellow = r.yellow, grey = r.grey,
            ups = r.ups, est = est, mats = mats, known = isKnown, makes = r.makes }
    end

    -- Recipes you know that make a material (Inscription's inks): the plan
    -- can craft it instead of buying it.
    local makers = {}
    for _, r in ipairs(recipes) do
        if r.known and r.makes and (r.makes.n or 0) > 0 then
            for _, id in ipairs(r.makes.ids) do makers[id] = makers[id] or r end
        end
    end

    -- Get `need` of one material (any of `ids`, lowest rank first) out of
    -- stock `p`: what you own first, then the cheapest of buying it, crafting
    -- it with a recipe you know, or milling herbs for it (pigments), each
    -- tried on a scratch view first. Only a recipe's own materials can be
    -- crafted, and only down to herbs (ink <- pigment <- herb): trying every
    -- maker at every level branched too much to finish (2026-11-03).
    -- Returns what has to be bought (copper; nil = no way to get it) and the
    -- value of your own stock it used. out (optional) records it: buy[id],
    -- used[id], make[recipe] = crafts, mill[MILL entry] = pigments milled.
    -- Stock keys: itemID = what you own; "x"..itemID = made earlier in the
    -- plan and not used yet (the second ink of a craft, the pigments a whole
    -- mill gives beyond what was needed, a leveling craft's output). Those
    -- are used first and aren't "from your own materials".
    local Get, Use, Make
    function Get(ids, need, p, out, depth, price, buyID)
        local own = 0
        for _, id in ipairs(ids) do
            local xk = "x" .. id
            local x = math.min(need, p[xk])
            if x > 0 then
                need = need - x
                p[xk] = p[xk] - x
            end
            if need <= 1e-9 then break end
            local use = math.min(need, p[id] or 0)
            if use > 0 then
                need = need - use
                p[id] = p[id] - use
                own = own + use * (value[id] or 0)
                if out then out.used[id] = (out.used[id] or 0) + use end
            end
        end
        if need <= 1e-9 then return 0, own end

        local best, bestScore
        -- craft now: a reagent a merchant you visited sells (Songwater) counts as on hand
        local canBuy = price and (not noBuy or (VoidAH_VendorPrice and VoidAH_VendorPrice(buyID)))
        if canBuy then best, bestScore = "buy", need * price end
        if depth == 0 then
            local maker
            for _, id in ipairs(ids) do maker = maker or makers[id] end
            if maker then
                local b, o = Make(maker, need, Scratch(p), nil, depth)
                if b and (not bestScore or b + OWN_WEIGHT * o < bestScore) then best, bestScore = maker, b + OWN_WEIGHT * o end
            end
        end
        if depth <= 1 then
            local e = canMill and millOf[ids[1]]
            if e then
                local b, o = Make(e, need, Scratch(p), nil, depth)
                if b and (not bestScore or b + OWN_WEIGHT * o < bestScore) then best, bestScore = e, b + OWN_WEIGHT * o end
            end
        end

        if best == "buy" then
            if out then out.buy[buyID] = (out.buy[buyID] or 0) + need end
            return need * price, own
        elseif best then
            local b, o = Make(best, need, p, out, depth)
            return b, own + o
        end
        if out then   -- no price and no way to make it: still on the list
            out.buy[buyID] = (out.buy[buyID] or 0) + need
        end
        return nil, own
    end

    -- Make `need` of a material with `how` (a recipe you know, or a MILL
    -- entry) in whole crafts / whole mills of MILL_HERBS herbs; what comes out
    -- beyond `need` goes into stock for later. Returns like Get.
    function Make(how, need, p, out, depth)
        local b, o, id, made
        if how.makes then
            local crafts = math.ceil(need / how.makes.n - 1e-9)
            if out then out.make[how] = (out.make[how] or 0) + crafts end
            b, o = Use(how, crafts, p, out, depth + 1)
            id, made = how.makes.ids[1], crafts * how.makes.n
        else
            local y = MillYield(how)
            local herbs = math.ceil(need / y / MILL_HERBS - 1e-9) * MILL_HERBS
            if out then out.mill[how] = (out.mill[how] or 0) + herbs end
            -- A mill is ten herbs of ONE rank: whole mills from each rank you own,
            -- then the rest of rank 1 (what you have, topped up by buying), so five
            -- of each rank never count as a mill (Astra, 2026-11-03).
            local left
            b, o, left = 0, 0, herbs
            for _, hid in ipairs(how.herbs) do
                local whole = math.floor(math.min(p[hid] or 0, left) / MILL_HERBS) * MILL_HERBS
                if whole > 0 then
                    p[hid] = p[hid] - whole
                    left = left - whole
                    o = o + whole * (value[hid] or 0)
                    if out then out.used[hid] = (out.used[hid] or 0) + whole end
                end
            end
            if left > 0 then
                local r1 = how.herbs[1]
                local bb, oo = Get({ r1 }, left, p, out, depth + 1, (UnitPrice({ r1 })), r1)
                o = o + oo
                b = bb and (b + bb) or nil
            end
            id, made = how.pigments[1], herbs * y
        end
        p["x" .. id] = p["x" .. id] + made - need
        return b, o
    end

    -- `n` crafts' worth of a recipe's materials out of stock `p`: what has to
    -- be bought (nil = a material you can't get) and the value of your stock used.
    function Use(r, n, p, out, depth)
        local buy, own, missing = 0, 0, false
        for _, m in ipairs(r.mats) do
            local b, o = Get(m.ids, m.n * n, p, out, depth or 0, m.price, m.id)
            own = own + o
            if b then buy = buy + b else missing = true end
        end
        return (not missing) and buy or nil, own
    end

    -- Your skill in THIS expansion's line (Midnight Alchemy): from the game when
    -- it has it loaded, else what VoidAH recorded at your profession window. Never
    -- the base profession numbers: those can be another line's (the tab once
    -- showed 100/75 for a 51/100 Midnight Alchemy).
    local live
    if C_TradeSkillUI and C_TradeSkillUI.GetProfessionInfoBySkillLineID then
        local ok, info = pcall(C_TradeSkillUI.GetProfessionInfoBySkillLineID, prof.tier)
        if ok and info and (info.maxSkillLevel or 0) > 0 then
            live = { skill = info.skillLevel or 0, max = info.maxSkillLevel }
        end
    end
    live = live or (cache and cache.tiers and cache.tiers[prof.tier])
    skill = live and live.skill or 0

    -- Craft by craft: the cheapest cost per expected point at the current skill,
    -- from the recipes you know; when none of them gives skill, the cheapest one
    -- you don't know yet (flagged NOT LEARNED), so the path still reaches the cap.
    -- A character with only old-expansion recipes (seen 2026-10-30) gets the full
    -- path and learns what to pick up.
    -- Skill moves in whole points: at skill s the chance of a skill-up is fixed,
    -- so the next success takes 1/chance crafts on average and adds `ups` points.
    -- (Adding the expected gain as a fraction made the chance drop before a real
    -- point was earned, and the plan stopped short of grey.)
    local s = math.max(skill or 0, 1)
    local start = s
    local steps, cur, guard = {}, nil, 0
    while s < target and guard < 1000 do
        guard = guard + 1
        local best, bestCPP, bestChance
        -- 1: known recipes, 2: ones you don't know; a recipe you know may grind
        -- out the last points at low odds before you're sent to learn a new one
        -- for a single point. 3: anything with any chance at all, so the odds
        -- floors never end the path short of the cap.
        for pass = 1, 3 do
            if best then break end
            local floor = pass == 1 and 0.02 or pass == 2 and 0.05 or 0
            for _, r in ipairs(recipes) do
                if (pass == 3 or r.known == (pass == 1)) and r.min <= s and s < r.grey then
                    local chance = 1
                    if s >= r.yellow and r.grey > r.yellow then chance = (r.grey - s) / (r.grey - r.yellow) end
                    -- priced as the whole expected batch (1/chance crafts): one
                    -- craft your stock covers can still leave the rest to buy
                    local buy, own
                    if chance > 0 and chance >= floor then buy, own = Use(r, 1 / chance, Scratch(pool)) end
                    if buy then
                        -- points past the cap are worth nothing: at 99, a +5 recipe
                        -- buys one point like a +1 does
                        local cpp = (buy + OWN_WEIGHT * own) / math.min(r.ups, target - s)
                        if not bestCPP or cpp < bestCPP then best, bestCPP, bestChance = r, cpp, chance end
                    end
                end
            end
        end
        if not best then break end
        if not cur or cur.r ~= best then
            cur = { r = best, from = s, count = 0 }
            steps[#steps + 1] = cur
        end
        -- expected crafts for this skill-up; your stock goes down by whole
        -- crafts, as the step's rounded-up count will use it (else later
        -- recipes would be picked on stock this step already took)
        local had = math.ceil(cur.count - 1e-6)
        cur.count = cur.count + 1 / bestChance
        local now = math.ceil(cur.count - 1e-6)
        if now > had then
            Use(best, now - had, pool)
            -- what a leveling craft makes can feed a later step (inks)
            if best.makes then
                local xk = "x" .. best.makes.ids[1]
                pool[xk] = pool[xk] + (now - had) * best.makes.n
            end
        end
        s = math.min(s + best.ups, target)
        cur.to = s
    end
    for _, st in ipairs(steps) do st.count = math.ceil(st.count - 1e-6) end
    local reached = s

    -- Craft now: recipes you know that give skill at your skill, and how many
    -- you can craft from what you have (milling and inks included), nothing
    -- bought but a reagent a merchant you visited sells (Songwater: the first
    -- in-game test showed nothing to craft for want of a 0.36g vendor item,
    -- 2026-11-03). Orange first, then the most crafts.
    local craftNow = {}
    noBuy = true
    for _, r in ipairs(recipes) do
        if r.known and r.min <= start and start < r.grey then
            local chance = 1
            if start >= r.yellow and r.grey > r.yellow then chance = (r.grey - start) / (r.grey - r.yellow) end
            local lo, hi = 0, 512   -- most crafts that need nothing bought
            while lo < hi do
                local mid = math.floor((lo + hi + 1) / 2)
                if Use(r, mid, Scratch(Fresh(true))) then lo = mid else hi = mid - 1 end
            end
            if lo > 0 then
                -- which merchant reagents those crafts need ("+ 30 Thalassian Songwater from a vendor")
                local o = { buy = {}, used = {}, make = {}, mill = {} }
                Use(r, lo, Scratch(Fresh(true)), o)
                local vendor = {}
                for id, n in pairs(o.buy) do
                    if n > 1e-9 then vendor[#vendor + 1] = ("%d %s"):format(math.ceil(n - 1e-6), ItemName(id)) end
                end
                table.sort(vendor)
                craftNow[#craftNow + 1] = { name = r.name, crafts = lo, chance = chance, spellID = r.id,
                    vendor = #vendor > 0 and table.concat(vendor, ", ") or nil }
            end
        end
    end
    noBuy = false
    table.sort(craftNow, function(a, b)
        if (a.chance >= 1) ~= (b.chance >= 1) then return a.chance >= 1 end
        return a.crafts > b.crafts
    end)

    -- Shape it for the tab: steps, totals per material, notes.
    local plan = { id = entry.id, name = entry.name .. " leveling", skill = entry.skill, steps = {}, mats = {},
        skillLevel = live and live.skill, maxSkillLevel = live and live.max, skillUnknown = not live }
    -- The rounded craft counts, step by step, take from a fresh copy of your
    -- stock: what's left goes on the list to buy.
    local stock = Fresh()
    local out = { buy = {}, used = {}, make = {}, mill = {} }
    local buyN, usedN = out.buy, out.used
    local totalCost, ownValue, anyEst, toLearn, noPrice = 0, 0, false, 0, false
    for _, st in ipairs(steps) do
        local buy, own = Use(st.r, st.count, stock, out)
        if buy then totalCost = totalCost + buy else noPrice = true end
        ownValue = ownValue + own
        if st.r.makes then
            local xk = "x" .. st.r.makes.ids[1]
            stock[xk] = stock[xk] + st.count * st.r.makes.n
        end
    end
    local order = {}
    for id, n in pairs(buyN) do
        if n > 1e-9 then order[#order + 1] = id end
    end
    for _, st in ipairs(steps) do
        local per = {}
        for _, m in ipairs(st.r.mats) do
            per[#per + 1] = m.n .. "x " .. ItemName(m.id)
        end
        if st.r.est then anyEst = true end
        if not st.r.known then toLearn = toLearn + 1 end
        plan.steps[#plan.steps + 1] = {
            startSkill = st.from, endSkill = math.max(st.to or st.from, st.from), recipe = st.r.name,
            spellID = st.r.id, count = st.count, per = table.concat(per, ", "), known = st.r.known,
            source = (not st.r.known) and "a trainer, vendor or renown" or nil,
        }
    end
    -- Only what's left to buy goes in the materials list (and its Add all).
    table.sort(order, function(a, b) return buyN[a] > buyN[b] end)
    for _, id in ipairs(order) do
        local price, src = UnitPrice({ id })
        local priceText = price and (Money(price) .. (src == "est" and " est." or src == "vendor" and " vendor" or "") .. " each") or "no price yet"
        plan.mats[#plan.mats + 1] = { math.ceil(buyN[id] - 1e-6), ItemName(id), id, priceText }
    end

    -- What the path takes from your stock, ranks of one material together:
    -- "60x Tranquility Bloom: this character 10, Alt 50".
    local fromRows, byName = {}, {}
    for id, n in pairs(usedN) do
        if n > 0 then
            local name = ItemName(id)
            local row = byName[name]
            if not row then
                row = { name = name, n = 0, where = {} }
                byName[name] = row
                fromRows[#fromRows + 1] = row
            end
            row.n = row.n + n
            for k, c in pairs(where[id] or {}) do row.where[k] = (row.where[k] or 0) + c end
        end
    end
    table.sort(fromRows, function(a, b) return a.n > b.n end)

    plan.craftNow, plan.made, plan.fromOwn = craftNow, {}, {}
    plan.totalCost, plan.ownValue, plan.start, plan.reached = totalCost, ownValue, start, reached
    local notes = {}
    if #steps == 0 then
        notes[#notes + 1] = (start >= target) and ("|cff66ff66You're at " .. target .. ": nothing left to level.|r")
            or "|cffff8800No recipe gives skill from here.|r"
        plan.summary = notes[1]
    else
        notes[#notes + 1] = ("Cheapest path from |cffffffff%d|r to |cffffffff%d|r: about |cffffd200%s|r to buy (%s%s)."):format(
            start, reached, Money(totalCost), VoidAH_Price and "VoidAH prices" or "listed prices; VoidAH adds your Auction House prices",
            anyEst and "; |cffaaaaaaest.|r = no Auction House price yet" or "")
        plan.summary = notes[1]
        if noPrice then
            notes[#notes + 1] = "|cffaaaaaaSome materials to buy have no price yet, so the total is low.|r"
        end
        if reached < target then
            notes[#notes + 1] = ("|cffff8800No recipe gives skill past %d.|r"):format(reached)
        end
        -- Made along the way instead of bought: mill first, then craft.
        local made = {}
        for _, e in ipairs(MILL) do
            local herbs = out.mill[e]
            if herbs and herbs > 0 then
                local y, est = MillYield(e)
                made[#made + 1] = ("  Mill %d %s (%d mills) for ~%d %s%s"):format(herbs, ItemName(e.herbs[1]),
                    herbs / MILL_HERBS, math.floor(herbs * y), ItemName(e.pigments[1]),
                    est and "  |cffaaaaaa(yield est. until you've milled some)|r" or "")
            end
        end
        local crafts = {}
        for r, n in pairs(out.make) do crafts[#crafts + 1] = { r = r, n = math.ceil(n - 1e-6) } end
        table.sort(crafts, function(a, b) return a.r.name < b.r.name end)
        for _, c in ipairs(crafts) do
            made[#made + 1] = ("  Craft %dx %s (makes %d)"):format(c.n, c.r.name, c.n * c.r.makes.n)
        end
        plan.made = made
        if #made > 0 then
            notes[#notes + 1] = "|cffffd200Make first|r |cffaaaaaa(cheaper than buying them)|r:"
            for _, line in ipairs(made) do notes[#notes + 1] = line end
        end
        for _, row in ipairs(fromRows) do
            local n = math.ceil(row.n - 1e-6)
            plan.fromOwn[#plan.fromOwn + 1] = ("  %dx %s  |cffaaaaaa%s|r"):format(n, row.name, FromText(row.where, n))
        end
        if #fromRows > 0 then
            notes[#notes + 1] = ("|cffffd200From your own materials|r |cffaaaaaa(worth about %s on the AH; already off the list to buy)|r:"):format(Money(ownValue))
            for _, line in ipairs(plan.fromOwn) do notes[#notes + 1] = line end
        end
        if not allChars then
            notes[#notes + 1] = "|cffaaaaaaCounting this character and the warband bank. With VoidGather your other characters count too.|r"
        end
    end
    if reached < target and unpriced > 0 then
        notes[#notes + 1] = ("|cffaaaaaa%d recipe(s) left out: a material has no price yet. A full Auction House scan may fill them in.|r"):format(unpriced)
    end
    if toLearn > 0 then
        notes[#notes + 1] = ("|cffff8800%d step(s) use recipes you don't know yet|r (marked NOT LEARNED): get them first."):format(toLearn)
    end
    if not known or not live then
        plan.openWindow = ("|cffff8800Open your %s window once|r so the plan starts at your skill and uses the recipes you know."):format(entry.name)
        notes[#notes + 1] = plan.openWindow
    end
    -- what of your spare gear's disenchanting this plan counted on
    local de = {}
    for id, n in pairs(deStock) do
        if owned[id] ~= nil then de[#de + 1] = ("~%d %s"):format(n, ItemName(id)) end
    end
    if #de > 0 then
        table.sort(de)
        plan.deNote = ("|cffaaaaaaCounted as yours: what disenchanting your spare gear should give (VoidGear's Spares tab): %s. One per piece is an estimate.|r"):format(table.concat(de, ", "))
        table.insert(notes, 2, plan.deNote)
    end
    plan.allChars = allChars
    plan.notes = table.concat(notes, "\n")
    return plan
end
